update conversaciones set ultima_actividad = now()
where agente_id = '{{ $('Ctx').item.json.agente_id }}' and telefono = '{{ $('Ctx').item.json.telefono }}';
insert into conversacion_eventos (conversacion_id, tipo, detalle)
select id, 'guardrail', jsonb_build_object('regla', '{{ $('Chequear guardrails').item.json.regla }}')
from conversaciones where agente_id = '{{ $('Ctx').item.json.agente_id }}' and telefono = '{{ $('Ctx').item.json.telefono }}'
  and '{{ $('Chequear guardrails').item.json.bloqueado }}' = 'true';

update conversaciones set variables_recolectadas = coalesce(variables_recolectadas,'{}'::jsonb) || jsonb_build_object('nombre','{{ ($('Ctx').item.json.nombre || '').replace(/['\\;]/g,'') }}')
where agente_id = '{{ $('Ctx').item.json.agente_id }}' and telefono = '{{ $('Ctx').item.json.telefono }}'
  and coalesce(variables_recolectadas->>'nombre','') = '' and '{{ ($('Ctx').item.json.nombre || '').replace(/['\\;]/g,'') }}' <> '';

