function partir(txt, max){
  txt = String(txt||'').trim();
  max = max || 700;
  if (txt.length <= max) return txt ? [txt] : [];
  var out=[]; var paras=txt.split(new RegExp('\\n\\s*\\n')).map(function(s){return s.trim();}).filter(Boolean);
  var buf='';
  for (var i=0;i<paras.length;i++){ var p=paras[i];
    if ((buf?buf+'\n\n'+p:p).length<=max){ buf=buf?buf+'\n\n'+p:p; }
    else { if(buf){out.push(buf);buf='';}
      if(p.length<=max){ buf=p; }
      else { var sents=p.match(new RegExp('[^.!?]+[.!?]*\\s*','g'))||[p]; var sb='';
        for(var j=0;j<sents.length;j++){ var s=sents[j].trim(); if(!s)continue;
          if((sb?sb+' '+s:s).length<=max){ sb=sb?sb+' '+s:s; }
          else { if(sb)out.push(sb); sb=(s.length<=max?s:s.slice(0,max)); } }
        buf=sb; }
    }
  }
  if(buf)out.push(buf);
  return out.length?out:[txt];
}
const LONGMAX = (()=>{ try { return $('Cargar contexto').first().json.agente.long_max_mensaje || 200; } catch(e){ return 200; } })();

const guardrails = $('Cargar contexto').first().json.guardrails || [];
let texto = ($('AI Agent').item.json.output) || '';
let bloqueado = false, regla = '';
for (const g of guardrails) {
  try { if (g.patron && new RegExp(g.patron, 'i').test(texto)) { bloqueado = true; regla = g.nombre; break; } } catch (e) {}
}
const final = bloqueado
  ? 'Esa información te la puede dar de forma personalizada un asesor académico. ¿Querés que te conecte con uno? 😊'
  : texto;
let pdf_a_enviar = '';
const _m = String(final).match(/\[\[PDF:(.*?)\]\]/);
if (_m) pdf_a_enviar = _m[1].trim();
let agenda_a_registrar = '';
const _ma = String(final).match(/\[\[AGENDA:(.*?)\]\]/);
if (_ma) { const _iso = _ma[1].trim(); if (_iso && _iso !== 'null' && !isNaN(Date.parse(_iso))) agenda_a_registrar = _iso; }
// pdf-url-resolver: si el LLM mando el nombre en vez de la URL, lo resolvemos
if (pdf_a_enviar && !/^https?:/i.test(pdf_a_enviar)) {
  const _pdfs = (()=>{ try { return $('Cargar contexto').first().json.pdfs || []; } catch(e){ return []; } })();
  const k = pdf_a_enviar.toLowerCase().replace(/.pdf$/,'');
  const hit = _pdfs.find(p=>String(p.nombre||'').toLowerCase()===k || String(p.programa||'').toLowerCase()===k)
    || _pdfs.find(p=>{const n=String(p.nombre||'').toLowerCase(); return n && (n.includes(k)||k.includes(n));})
    || _pdfs.find(p=>String(p.url||'').toLowerCase().includes(k));
  pdf_a_enviar = hit ? hit.url : '';
}
// sanitizador WhatsApp: markdown -> formato WhatsApp
const _wa = (s) => String(s||'')
  .replace(/^\s*(transferir|faq_kb|consulta_cursos|envio_links|agendamiento|checkout_link|consulta_precios)\s*\n/i, '') // linea-tool suelta
  .replace(/\s*\[PDF adjunto\]\.?/gi, '') // pdf-adjunto-literal

  .replace(/\*\*(.+?)\*\*/g, '*$1*')
  .replace(/^#{1,6}\s+(.+)$/gm, '*$1*')
  .replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g, '$1: $2')
  .replace(/^\s*[-•]\s+/gm, '- ');
const final_limpio = _wa(String(final).replace(/\[\[PDF:.*?\]\]/g,'').replace(/\[\[AGENDA:.*?\]\]/g,'').trim());
return [{ json: { respuesta_final: final_limpio, mensajes: partir(final_limpio, LONGMAX), bloqueado, regla, pdf_a_enviar, agenda_a_registrar } }];

const agente = $('Cargar contexto').first().json.agente;
const tz = agente.zona_horaria || 'America/Mexico_City';
const data = $('Cargar contexto').first().json;
const horarios = data.horarios || [];
const feriados = (data.feriados || []).map(f => String(f).slice(0,10));
const wd = {Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6};
const dias = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const now = new Date();
const P = d => Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false,weekday:'short'}).formatToParts(d).map(x=>[x.type,x.value]));
const p = P(now);
const fecha = `${p.year}-${p.month}-${p.day}`;
const hhmm = `${p.hour}:${p.minute}`;
const dia = wd[p.weekday];
const esFeriado = feriados.includes(fecha);
const hoy = horarios.find(h=>h.dia===dia);
let abierto = false;
if (!esFeriado && hoy && !hoy.cerrado && hoy.inicio && hoy.fin) abierto = hhmm >= String(hoy.inicio).slice(0,5) && hhmm <= String(hoy.fin).slice(0,5);
function tzOffsetMin(d){
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:tz,hour12:false,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}).formatToParts(d).map(x=>[x.type,x.value]));
  const asUTC = Date.UTC(parts.year, parts.month-1, parts.day, parts.hour, parts.minute, parts.second);
  return (asUTC - d.getTime())/60000;
}
function localToISO(f, ini){
  const [Y,M,D] = f.split('-').map(Number);
  const [hh,mm] = String(ini).slice(0,5).split(':').map(Number);
  const guess = Date.UTC(Y, M-1, D, hh, mm);
  const off = tzOffsetMin(new Date(guess));
  return new Date(guess - off*60000).toISOString();
}
function nextSlot(){
  for (let off=0; off<14; off++){
    const d = new Date(now.getTime()+off*86400000); const q = P(d);
    const f = `${q.year}-${q.month}-${q.day}`; const w2 = wd[q.weekday];
    if (feriados.includes(f)) continue;
