const nz = $json;
const raw = nz._raw || {};
const msgs = Array.isArray(raw.messages) ? raw.messages : [];
const m = msgs[0] || {};
let direccion = 'sistema';
if (m.fromCustomer === true || m.from === 'user') direccion = 'lead';
else if (m.from === 'operator' || m.from === 'agent' || m.operatorId) direccion = 'asesor';
else if (m.from === 'bot') direccion = 'bot';
let texto = nz.mensaje || m.message || '';
let tipo;
if (raw.type === 'event') { tipo = 'evento'; if (!texto) { try { texto = JSON.stringify(raw.events || raw.info || {}).slice(0, 300); } catch(e){} } }
else if (texto) tipo = 'texto';
else {
  const ct = String(m.contentType || m.type || m.mediaType || '').toLowerCase();
  if (ct.includes('audio') || m.audioUrl) tipo = 'audio';
  else if (ct.includes('image')) tipo = 'imagen';
  else if (m.mediaUrl || ct) tipo = ct ? ct.slice(0,30) : 'media';
  else tipo = 'sin_texto';
}
return [{ json: { p: [ String(nz.agente_id||''), String(nz.telefono||''), String(nz.canal||''), direccion, tipo, String(texto||''), String(nz.queue_in || m.queue || ''), String(nz.msg_id || m._id_ || ''), JSON.stringify(raw) ] } }];

const ctx = $('Ctx').first().json;
let vision = '';
try {
  const r = $('Leer imagen').first().json;
  vision = String((((r.choices || [])[0] || {}).message || {}).content || '').trim();
} catch (e) {}
const partes = [String(ctx.mensaje || '').trim()];
